        {
            // Tạo biến để lưu trữ thông tin hack
            bool antiBan = true;
            bool tựBắn = true;

            // Tạo hàm để thực hiện hack
            void Hack()
            {
                // Thực hiện hack
                Console.WriteLine("Hack thành công!");
            }

            // Thực hiện hack
            Hack();

            // Kiểm tra anti ban
            if (antiBan)
            {
                // Thực hiện anti ban
                Console.WriteLine("Anti ban hoạt động!");
            }

